from typing import Any


class QuorumCluster:
    """Coordinates distributed consensus across a cluster of N nodes using quorum-based consistency."""

    def __init__(self, node_ids: list[str]) -> None:
        """
        Initializes cluster state with given unique node IDs.
        Quorum threshold is floor(N / 2) + 1.
        """
        self.node_ids: list[str] = list(node_ids)
        self.n: int = len(self.node_ids)
        self.quorum_threshold: int = (self.n // 2) + 1

        # Store per-node state: node_id -> {key: (version, value)}
        self._node_store: dict[str, dict[str, tuple[int, Any]]] = {
            node_id: {} for node_id in self.node_ids
        }
        # Logical timestamp/version counter for total write ordering
        self._version_counter: int = 0
        # Active network partitions represented as a list of disjoint node sets
        self._partitions: list[set[str]] = [set(self.node_ids)]

    def _get_partition(self, node_id: str) -> set[str]:
        """Returns the partition set containing the specified node."""
        for part in self._partitions:
            if node_id in part:
                return part
        return {node_id}

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """
        Divides cluster into isolated network partitions where group_a can only talk
        to group_a, and group_b only to group_b. Any unassigned nodes remain isolated.
        """
        set_a = set(group_a)
        set_b = set(group_b)
        partitions: list[set[str]] = [set_a, set_b]

        assigned_nodes = set_a | set_b
        for node in self.node_ids:
            if node not in assigned_nodes:
                partitions.append({node})

        self._partitions = partitions

    def heal_partition(self) -> None:
        """
        Restores full network connectivity and synchronizes committed state
        across all nodes by propagating the latest version of each key.
        """
        # Restore full connectivity across all nodes
        self._partitions = [set(self.node_ids)]

        # Determine the latest committed version for each key across the cluster
        latest_state: dict[str, tuple[int, Any]] = {}
        for node_id in self.node_ids:
            for key, (ver, val) in self._node_store[node_id].items():
                if key not in latest_state or ver > latest_state[key][0]:
                    latest_state[key] = (ver, val)

        # Synchronize committed state to every node in the cluster
        for node_id in self.node_ids:
            self._node_store[node_id] = dict(latest_state)

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """
        Proposes a write from from_node.
        Commits and updates all nodes in the partition if partition size >= quorum threshold.
        Rejects write if in a minority partition.
        """
        if from_node not in self._node_store:
            return False

        partition = self._get_partition(from_node)
        if len(partition) >= self.quorum_threshold:
            self._version_counter += 1
            entry = (self._version_counter, value)
            for node in partition:
                if node in self._node_store:
                    self._node_store[node][key] = entry
            return True

        return False

    def read_value(self, from_node: str, key: str) -> Any:
        """
        Returns the committed value for key on from_node (or None if not set).
        """
        if from_node not in self._node_store:
            return None

        node_data = self._node_store[from_node]
        if key in node_data:
            return node_data[key][1]

        return None
